import altair as alt
import numpy as np
import pandas as pd
from IPython.display import HTML, display

slider_style = """
<style>
.vega-embed {
  align-items: center;
}
.vega-bindings {
  width: min(360px, 100%);
  margin: 0.75rem 0 0 34px;
}
.vega-bind {
  display: flex;
  align-items: center;
  width: 100%;
  font-size: 18px;
  line-height: 1.2;
  white-space: nowrap;
}
.vega-bind input[type="range"] {
  flex: 1 1 auto;
  min-width: 220px;
  margin-left: 0.35rem;
  margin-right: 0.75rem;
  transform: translateY(2.4px);
}
.vega-bind input[type="number"] {
  width: 3.25rem;
  font-size: 16px;
  line-height: 1.2;
  text-align: center;
}
</style>
"""

display(HTML(slider_style))

rng = np.random.default_rng(8)
q, _ = np.linalg.qr(rng.normal(size=(8, 8)))
eigvals = np.array([4.0, -3.88, 3.55, -3.32, 2.95, -2.70, 2.35, -2.05])
a_qr_demo = q @ np.diag(eigvals) @ q.T

records = []
a_k = a_qr_demo.copy()
for k in range(65):
    for row in range(a_k.shape[0]):
        for column in range(a_k.shape[1]):
            records.append({
                "k": k,
                "row": row,
                "column": column,
                "value": a_k[row, column],
            })

    q_k, r_k = np.linalg.qr(a_k)
    a_k = r_k @ q_k

qr_iterations = pd.DataFrame(records)

k_slider = alt.param(
    name="k",
    value=0,
    bind=alt.binding_range(min=0, max=64, step=1, name="𝑘 = "),
)

chart = (
    alt.Chart(qr_iterations)
    .mark_rect(stroke="white", strokeWidth=0.5)
    .encode(
        x=alt.X(
            "column:O",
            axis=alt.Axis(
                title=None,
                orient="top",
                labelAngle=0,
                labelFontSize=15,
            ),
        ),
        y=alt.Y(
            "row:O",
            axis=alt.Axis(title=None, labelFontSize=15),
            sort="ascending",
        ),
        color=alt.Color(
            "value:Q",
            scale=alt.Scale(
                domain=[-4, 0, 4],
                range=["#3c4cc0", "#dddddd", "#bf0026"],
            ),
            legend=alt.Legend(
                title=None,
                labelFontSize=15,
                labelOffset=6,
                gradientLength=300,
                gradientThickness=18,
                gradientStrokeColor="black",
                gradientStrokeWidth=0.8,
            ),
        ),
        tooltip=[
            alt.Tooltip("row:O", title="row"),
            alt.Tooltip("column:O", title="column"),
            alt.Tooltip("value:Q", title="value", format=".3f"),
        ],
    )
    .add_params(k_slider)
    .transform_filter(alt.datum.k == k_slider)
    .properties(width=300, height=300)
    .configure_view(stroke="black", strokeWidth=1)
)

chart
